sys_script_include.script:
var GetDefaultVariables3 = Class.create();
GetDefaultVariables3.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    GetDefaultVariablesvalue: function() {
        try {
            var ritmID = this.getParameter("sys_id");
            var ritm = new GlideRecord("sc_req_item");
            ritm.get(ritmID);

            var returnVariables = {};
            for (var key in ritm.variables) {
                returnVariables[key] = ritm.variables[key] + ' ';
            }
            return JSON.stringify(returnVariables);

        } catch (e) {
            gs.error('GetDefaultVariables 异常：' + e);
            return 'exception';
        }
	},
    type: 'GetDefaultVariables3'
});
